('698735d1-f1a0-484f-821b-6e4038f6ebab', '11.02.2026 13:29:41', 'admin', null, null, '41', '', true, '0', '1.5.8', 'Кнасос.стан', '', 'Показатель наличия акта опробования работоспособности оборудования насосных станций', 'Акт опробования работоспособности оборудования насосных станций, проведение которого установлено требованиями пункта 388 Правил N 511 (подпункт 9.3.24 Пункта 9 Правил)', '0.01', '7909c321-f77c-4bdf-9d4d-e618fac50c81'), 
('0d075ac3-7c40-46b9-9953-aca46a59a3bd', '11.02.2026 13:29:41', 'admin', null, null, '42', '', true, '1', '1.5.9', 'Кматер', '', 'Показатель наличия запасов материалов, запорной арматуры, запасных частей, средств механизации', 'Утвержденный в соответствии с требованиями пункта 28 Правил N 511 перечень запасов материалов, запорной арматуры, запасных частей, средств механизации для выполнения срочных внеплановых (аварийных) ремонтных работ, результаты последней проведенной инвентаризации запасов материалов, запорной арматуры, запасных частей, средств механизации для выполнения срочных внеплановых (аварийных) ремонтных работ, оформленные в соответствии с требованиями Положения по ведению бухгалтерского учета и бухгалтерской отчетности в Российской Федерации, утвержденного приказом Минфина России от 29 июля 1998 г. N 34н <5> (подпункт 9.3.26 Пункта 9 Правил)', '0.04', '7909c321-f77c-4bdf-9d4d-e618fac50c81'), 
